import { createMemo, createSignal, For, Show } from "solid-js";
import { BODY_FORMAL_FILE, BODY_FORMAT_KEY, BodyFormat } from "../../../fns/shared.js";
import { Badge } from "../../ui/Badge.jsx";
import IconButton from "../../ui/IconButton.jsx";
import Placeholder from "../../ui/Placeholder.jsx";
import { Section } from "../../ui/Section.jsx";
import { Select, SelectOption } from "../../ui/Select.jsx";
import { Tab, TabGroup, TabList, TabPanel } from "../../ui/Tabs.jsx";
import { Text } from "../../ui/Text.jsx";
import { FunctionIcon, TrashIcon } from "../icons.jsx";
import { BlobViewer } from "./BlobViewer.jsx";
import { FormDataViewer } from "./FormDataViewer.jsx";
import { HeadersViewer } from "./HeadersViewer.jsx";
import { HexViewer } from "./HexViewer.jsx";
import { SerovalViewer } from "./SerovalViewer.jsx";
import "./styles.css";
import { URLSearchParamsViewer } from "./URLSearchParamsViewer.jsx";
async function getFile(source) {
    const formData = await source.formData();
    const file = formData.get(BODY_FORMAL_FILE);
    if (!(file && file instanceof File)) {
        throw new Error("invalid file input");
    }
    return file;
}
async function getURLSearchParams(source) {
    const text = await source.text();
    return new URLSearchParams(text);
}
function ContentViewer(props) {
    const body = createMemo(() => {
        const original = props.source.source;
        if (!original.body) {
            return undefined;
        }
        const source = original.clone();
        const startType = source.headers.get(BODY_FORMAT_KEY);
        const contentType = source.headers.get("Content-Type");
        switch (true) {
            case startType === "true":
            case startType === BodyFormat.Seroval:
                return <SerovalViewer stream={source}/>;
            case startType === BodyFormat.String:
                return <HexViewer bytes={source.bytes()}/>;
            case startType === BodyFormat.File:
                return <BlobViewer source={getFile(source)}/>;
            case startType === BodyFormat.FormData:
            case contentType?.startsWith("multipart/form-data"):
                return <FormDataViewer source={source.formData()}/>;
            case startType === BodyFormat.URLSearchParams:
            case contentType?.startsWith("application/x-www-form-urlencoded"):
                return <URLSearchParamsViewer source={getURLSearchParams(source)}/>;
            case startType === BodyFormat.Blob:
                return <BlobViewer source={source.blob()}/>;
            case startType === BodyFormat.ArrayBuffer:
            case startType === BodyFormat.Uint8Array:
                return <HexViewer bytes={source.bytes()}/>;
        }
        return undefined;
    });
    return (<>
      <Show when={body()}>
        <Section title="Body">{body()}</Section>
      </Show>
      <Section collapsible title="Headers">
        <HeadersViewer headers={props.source.source.headers}/>
      </Section>
    </>);
}
function convertRequestToEntries(request) {
    return [
        ["Cache", request.cache],
        ["Credentials", request.credentials],
        ["Destination", request.destination],
        ["Integrity", request.integrity],
        ["Keep Alive", request.keepalive],
        ["Mode", request.mode],
        ["Redirect", request.redirect],
        ["Referrer", request.referrer],
        ["Referrer Policy", request.referrerPolicy],
        ["URL", request.url],
    ];
}
function RequestViewer(props) {
    return (<TabPanel value="request">
      <ContentViewer source={props.request}/>
      <Section collapsible defaultOpen={false} title="Information">
        <div data-start-properties data-start-kv-table>
          <For each={convertRequestToEntries(props.request.source)}>
            {([key, value]) => (<div data-start-property data-start-kv-row>
                <Text data-start-kv-key options={{ size: "xs", weight: "semibold", font: "mono", wrap: "nowrap" }}>
                  {key}
                </Text>
                <Text data-start-kv-value options={{ size: "xs", font: "mono", wrap: "wrap" }}>
                  {`${value}`}
                </Text>
              </div>)}
          </For>
        </div>
      </Section>
    </TabPanel>);
}
function convertResponseToEntries(response) {
    return [
        ["OK", response.ok],
        ["Redirected", response.redirected],
        ["Status", response.status],
        ["Status Text", response.statusText],
        ["Type", response.type],
        ["URL", response.url],
    ];
}
function ResponseViewer(props) {
    return (<TabPanel value="response">
      <Show when={props.response} fallback={<Placeholder>
            <Text options={{ size: "xs" }}>Waiting for response.</Text>
          </Placeholder>}>
        {instance => (<>
            <ContentViewer source={instance()}/>
            <Section collapsible defaultOpen={false} title="Information">
              <div data-start-properties data-start-kv-table>
                <For each={convertResponseToEntries(instance().source)}>
                  {([key, value]) => (<div data-start-property data-start-kv-row>
                      <Text data-start-kv-key options={{ size: "xs", weight: "semibold", font: "mono", wrap: "nowrap" }}>
                        {key}
                      </Text>
                      <Text data-start-kv-value options={{ size: "xs", font: "mono", wrap: "wrap" }}>
                        {`${value}`}
                      </Text>
                    </div>)}
                </For>
                <div data-start-property data-start-kv-row>
                  <Text data-start-kv-key options={{ size: "xs", weight: "semibold", font: "mono", wrap: "nowrap" }}>
                    Timing
                  </Text>
                  <Text data-start-kv-value options={{ size: "xs", font: "mono", wrap: "wrap" }}>
                    {`${((instance().time - props.request.time) / 1000).toFixed(2)}s`}
                  </Text>
                </div>
              </div>
            </Section>
          </>)}
      </Show>
    </TabPanel>);
}
function ServerFunctionInstanceDetail(props) {
    return (<>
      <span data-start-functions-instance-detail>
        <Badge type="info">{props.value.request.source.method}</Badge>
        <Text options={{ size: "xs" }}>{props.id}</Text>
      </span>
      <Show when={props.value.response}>
        {response => {
            if (response().source.ok) {
                return <Badge type="success">{response().source.status}</Badge>;
            }
            return <Badge type="failure">{response().source.status}</Badge>;
        }}
      </Show>
    </>);
}
function ServerFunctionInstanceViewer(props) {
    const [tab, setTab] = createSignal("request");
    return (<div data-start-function-instance-viewer>
      <div data-start-function-instance-viewer-nav>
        <div data-start-function-instance-viewer-nav-left>
          <div>
            <ServerFunctionInstanceDetail id={props.id} value={props.instance}/>
          </div>
        </div>
        <div>
          <Show when={props.instance.response}>
            {response => (<span data-start-function-instance-timing>
                <Text options={{ size: "xs", weight: "semibold", font: "mono", wrap: "nowrap" }}>
                  {`${((response().time - props.instance.request.time) / 1000).toFixed(2)}s`}
                </Text>
              </span>)}
          </Show>
          <IconButton onClick={props.onDelete}>
            <TrashIcon title="Delete instance"/>
          </IconButton>
        </div>
      </div>
      <div data-start-function-instance-viewer-content>
        <TabGroup horizontal value={tab()} onChange={value => setTab(value ?? "request")}>
          <TabList>
            <Tab value="request">Request</Tab>
            <Tab value="response">Response</Tab>
          </TabList>
          <RequestViewer request={props.instance.request}/>
          <ResponseViewer request={props.instance.request} response={props.instance.response}/>
        </TabGroup>
      </div>
    </div>);
}
function EmptyServerFunctions() {
    return (<Placeholder>
      <Text options={{ size: "xs" }}>No server function calls detected.</Text>
    </Placeholder>);
}
export function ServerFunctionViewer(props) {
    const [currentInstance, setCurrentInstance] = createSignal();
    const keys = createMemo(() => Object.keys(props.instances));
    return (<Show when={props.show}>
      <div data-start-dev-toolbar-panel>
        <div data-start-functions-viewer>
          {/* list of calls */}
          <div data-start-functions-sidebar>
            <div data-start-functions-nav>
              <FunctionIcon title="Server functions"/>
              <Text options={{ size: "sm" }}>Server functions</Text>
            </div>
            <div data-start-functions-instances-container>
              <Show when={keys().length} fallback={<EmptyServerFunctions />}>
                <Select data-start-functions-instances horizontal={false} value={currentInstance()} onChange={current => setCurrentInstance(current)}>
                  <For each={keys()}>
                    {instance => (<SelectOption value={instance}>
                        <Show when={props.instances[instance]}>
                          {current => (<ServerFunctionInstanceDetail id={instance} value={current()}/>)}
                        </Show>
                      </SelectOption>)}
                  </For>
                </Select>
              </Show>
            </div>
          </div>
          {/* request/response viewer */}
          <div data-start-functions-detail>
            <Show when={currentInstance()} fallback={<Placeholder>
                  <Text options={{ size: "xs" }}>Select a server function call.</Text>
                </Placeholder>}>
              {value => (<Show when={props.instances[value()]}>
                  {instance => (<ServerFunctionInstanceViewer id={value()} instance={instance()} onDelete={() => {
                    setCurrentInstance(undefined);
                    props.onDeleteInstance(value());
                }}/>)}
                </Show>)}
            </Show>
          </div>
        </div>
      </div>
    </Show>);
}
